#!/usr/bin/env node
// Three exact V7 scenes with currentP4 SYSTEM/schema, then up to three actual
// alternating replies in L's resulting conversation. At most six LOCAL calls.
// No forced proposal, acceptance, closure, retries, cloud or production state.
import { readFile, mkdir, open, unlink, stat } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { z } from 'zod';
import { loadFrozenV7Core, hash } from './benchmark-society-frozen-v7.mjs';
import { prepareOrderCases, parseArgs } from './benchmark-society-v7-deal-order-local.mjs';
import { loadCore, sourceManifest, captureSourceBundle, receive, decodedReceipt, processSample, MODEL } from './benchmark-society-runtime-v7-local.mjs';
import { atomicJson, responseText, BenchError } from './benchmark-society-models.mjs';
const ROOT=resolve(dirname(fileURLToPath(import.meta.url)),'..');
export const POLICY={version:1,protocol:4,maxCalls:6,matchedActors:['G','L','B'],replyBranch:'L',maxReplies:3,
 maxOutputTokens:1024,timeoutMs:120000,endpoint:'http://127.0.0.1:8018/v1/chat/completions',epochMs:Date.parse('2026-09-08T00:00:00Z'),generation:0};
const fail=code=>{throw new BenchError(code)};
const sceneHash=scene=>hash({state:scene.state,world:scene.world});
const cloned=fixture=>structuredClone(fixture.scene);
function prepared(core,scene,actor,sequence,nowMs) {
 return core.prepareSocietyJob({state:scene.state,world:scene.world,actor,sequence,nowMs,generation:0,worldRevision:scene.worldRevision,
  habitatId:'isolated-open-message-probe',protocolVersion:4});
}
export function matchedJob(core,fixture) {
 const source=fixture.sourceJob, current=prepared(core,fixture.scene,fixture.actor,source.turn.sequence,source.nowMs), job=structuredClone(source);
 if(hash(current.job.outputContract.jsonSchema)!==hash(core.proposalCapabilityChoiceJsonSchema(fixture.scene.state,fixture.scene.world,source.turn)))fail('matched_authority_changed');
 job.id=`open-message:matched:${source.id}`; job.job.jobId=job.id;
 job.job.prompt.system=current.job.prompt.system; job.job.outputContract=current.job.outputContract;
 job.payload.messages[0].content=current.job.prompt.system; job.payload.response_format.json_schema.schema=current.job.outputContract.jsonSchema;
 job.promptBytes=Buffer.byteLength(JSON.stringify({messages:job.payload.messages,response_format:job.payload.response_format}));
 job.stage='matched'; job.sourceJobHash=hash(source); job.beforeHash=fixture.beforeHash;
 if(job.job.outputContract.version!==4 || job.payload.max_tokens!==1024 || job.payload.chat_template_kwargs.enable_thinking!==false
  || job.job.prompt.user!==source.job.prompt.user || job.payload.seed!==source.payload.seed) fail('matched_context_changed');
 return job;
}
function replyJob(core,scene,actor,index) {
 const nowMs=POLICY.epochMs+40_000+index*1000, sequence=40+index;
 const p=prepared(core,scene,actor,sequence,nowMs), provider=core.workersAIInput(p.job,core.GEMMA_WORKERS_AI_MODEL);
 const payload={model:MODEL.id,messages:provider.messages,temperature:provider.temperature,seed:provider.seed,stream:false,max_tokens:1024,
  chat_template_kwargs:{enable_thinking:false},response_format:{type:'json_schema',json_schema:{name:'society_turn',schema:p.job.outputContract.jsonSchema,strict:true}}};
 return {id:p.job.jobId,actor,stage:'derived_reply',index,nowMs,...p,payload,reservedCalls:1,outputTokenLimit:1024,
  promptBytes:Buffer.byteLength(JSON.stringify({messages:payload.messages,response_format:payload.response_format})),beforeHash:sceneHash(scene)};
}
function application(core,scene,job,row) {
 if(row.receipt.receiptCode) return {ok:false,code:row.receipt.receiptCode,afterHash:sceneHash(scene)};
 if(!z.fromJSONSchema(job.job.outputContract.jsonSchema).safeParse(row.receipt.output).success) return {ok:false,code:'schema_violation',afterHash:sceneHash(scene)};
 scene.state=core.markSocietyAttempt(scene.state,job.actor,job.nowMs);
 const result=core.applyProposalCapabilityChoice(scene.state,scene.world,job.turn,row.receipt.output,{nowMs:job.nowMs+1,generation:0});
 const before=hash(scene.world);scene.state=result.state;scene.world=result.world;if(hash(scene.world)!==before)scene.worldRevision++;
 if(result.ok){const again=core.applyProposalCapabilityChoice(result.state,result.world,job.turn,row.receipt.output,{nowMs:job.nowMs+2,generation:0});
  if(again.code!=='already_applied'||sceneHash(again)!==sceneHash(result))fail('duplicate_effect');}
 if(!core.parseSocietyState(scene.state).ok)fail('invalid_state');
 return {ok:result.ok,code:result.code,afterHash:sceneHash(scene)};
}
export async function runScenario(core,fixtures,ledger,{persist=async()=>{},dispatch,beforeReserve,measure,maxNewCalls=1}={}) {
 if(!Number.isInteger(maxNewCalls)||maxNewCalls<0||maxNewCalls>6)fail('call_limit');
 const scenes=Object.fromEntries(fixtures.map(f=>[f.actor,cloned(f)]));let cursor=0,newCalls=0,halted=null;
 async function thought(scene,job){
  let row=ledger.entries[cursor];
  if(row){if(row.kind!=='cognition'||hash(row.job)!==hash(job))fail('saved_job_changed');}
  else {
   if(newCalls>=maxNewCalls){halted='call_limit_reached';return false;}
   if(ledger.entries.filter(r=>r.kind==='cognition').length>=6)fail('total_call_limit');
   row=await receive(job,ledger,persist,dispatch,core.parseStructuredPayload,{beforeReserve,measure});newCalls++;
  }
  cursor++;
  if(row.state==='completed'){
   const expected=application(core,scene,job,row);
   if(row.application&&hash(row.application)!==hash(expected))fail('replay_application');
   if(!row.application){row.application=expected;await persist(ledger);}
  }
  return true;
 }
 for(const fixture of fixtures)if(!await thought(scenes[fixture.actor],matchedJob(core,fixture)))return {scenes,newCalls,halted};
 const branch=scenes.L, l=fixtures.find(f=>f.actor==='L'), conversationId=l.sourceJob.turn.conversation?.id;
 let last=ledger.entries.find(r=>r.job?.stage==='matched'&&r.job.actor==='L');
 for(let i=0;i<3;i++){
  const conversation=branch.state.conversations.find(c=>c.id===conversationId);
  if(!last?.application?.ok||!conversation||conversation.status!=='open'||!conversation.nextSpeaker||!['J','L'].includes(conversation.nextSpeaker))break;
  const job=replyJob(core,branch,conversation.nextSpeaker,i);
  if(!await thought(branch,job))return {scenes,newCalls,halted}; last=ledger.entries[cursor-1];
 }
 if(ledger.entries[cursor]?.kind!=='watch'&&newCalls>=maxNewCalls&&maxNewCalls<6){halted='call_limit_reached';return {scenes,newCalls,halted};}
 const plans=core.plannedSocietyActions(branch.state,branch.world);
 if(Object.keys(plans).length){
  const beforeHash=sceneHash(branch),beforeAccounts=core.economicAccounts(branch.world),observations=[];
  core.advanceScheduledWatch(branch.world,undefined,undefined,undefined,{plans,onAction:o=>observations.push(o)});
  const observed=core.observeSocietyActions(branch.state,branch.world,observations,{nowMs:POLICY.epochMs+50_000});branch.state=observed.state;branch.world=observed.world;branch.worldRevision++;
  if(hash(core.observeSocietyActions(branch.state,branch.world,observations,{nowMs:POLICY.epochMs+50_001}))!==hash(observed))fail('duplicate_watch');
  const row={kind:'watch',id:'open-message:L:watch',beforeHash,plans,observations,beforeAccounts,afterAccounts:core.economicAccounts(branch.world),afterHash:sceneHash(branch)};
  if(ledger.entries[cursor]){if(hash(ledger.entries[cursor])!==hash(row))fail('replay_watch');}
  else{ledger.entries.push(row);await persist(ledger);}cursor++;
 }
 if(cursor!==ledger.entries.length)fail('unconsumed_entries');
 return {scenes,newCalls,halted};
}
function verifyLedger(core,ledger,config){
 if(ledger.binding!==hash(config)||hash(ledger.config)!==hash(config)||!Array.isArray(ledger.entries))fail('ledger_binding');
 const ids=new Set();let calls=0,watches=0;
 for(const row of ledger.entries){if(ids.has(row.id))fail('duplicate_id');ids.add(row.id);
  if(row.kind==='watch'){watches++;continue;}calls++;
  if(row.kind!=='cognition'||row.job.job.outputContract.version!==4||!['completed','reserved','failed','timeout','skipped'].includes(row.state))fail('ledger_row');
  if(row.state==='completed'){const raw=JSON.parse(row.rawResponse),parsed=decodedReceipt(raw,core.parseStructuredPayload,row.headers);
   if(hash(raw)!==hash(row.response)||hash(parsed)!==hash(row.receipt))fail('receipt_changed');}
  else if(row.application)fail('unknown_applied');
 }
 if(calls>6||watches>1)fail('ledger_cap');
}
async function localProvenance(frozen,pid){
 if(!processSample(pid)?.command.endsWith('omlx-server'))fail('owned_local_server');
 const listening=spawnSync('/usr/sbin/lsof',['-nP','-a','-p',String(pid),'-iTCP:8018','-sTCP:LISTEN'],{encoding:'utf8',timeout:3000});
 if(listening.status!==0||!listening.stdout.includes('127.0.0.1:8018 (LISTEN)'))fail('loopback_listener');
 for(const file of frozen.frozenReference.config.provenance.observedFiles){const path=join(MODEL.path,file.name),info=await stat(path);
  if(info.size!==file.bytes||info.ino!==file.inode||info.mtimeMs!==file.mtimeMs||info.ctimeMs!==file.ctimeMs)fail('weights_changed');
  if(!file.name.endsWith('.safetensors')&&hash(await readFile(path))!==file.sha256)fail('model_metadata_changed');}
 for(const file of frozen.frozenReference.config.provenance.serverSources)if(hash(await readFile(join('/Applications/oMLX.app/Contents/Resources/omlx',file.name)))!==file.sha256)fail('server_changed');
}
export async function main(args=process.argv.slice(2)){
 const options=parseArgs(args),frozen=await loadFrozenV7Core(),core=await loadCore();
 try{
  const fixtures=await prepareOrderCases(frozen),jobs=fixtures.map(f=>matchedJob(core,f));
  const scriptPaths=['scripts/benchmark-society-open-message-local.mjs','scripts/benchmark-society-v7-deal-order-local.mjs','scripts/benchmark-society-frozen-v7.mjs','scripts/benchmark-society-models.mjs'];
  const scripts=await Promise.all(scriptPaths.map(async path=>({path,sha256:hash(await readFile(join(ROOT,path)))})));
  const config={policy:POLICY,source:core.sourceFiles,frozen:frozen.frozenProvenance,scripts,model:MODEL,modelProvenance:frozen.frozenReference.config.provenance,
   intervention:'Matched cases retain exact V7 state and USER; currentP4 SYSTEM and corrected schema both change. Replies are newly derived, no forced deals or acceptance.',jobs:jobs.map(j=>({id:j.id,sha256:hash(j)}))};
  if(!options.run){console.log(JSON.stringify({mode:'offline',httpRequests:0,config},null,2));return;}
  const directory=resolve(options.out),path=join(directory,'ledger.json');await mkdir(directory,{recursive:true});const lock=await open(join(directory,'.lock'),'wx');
  try{
   let ledger;try{ledger=JSON.parse(await readFile(path));}catch(e){if(e.code!=='ENOENT')throw e;if(!options.maxNewCalls)fail('replay_requires_ledger');
    ledger={config,binding:hash(config),entries:[]};await atomicJson(join(directory,'source-bundle.json'),await captureSourceBundle(core.sourceFiles));
    await atomicJson(join(directory,'probe-source-bundle.json'),{files:await Promise.all(scripts.map(async file=>({...file,text:await readFile(join(ROOT,file.path),'utf8')})))});
    await atomicJson(join(directory,'frozen-cases.json'),{source:frozen.frozenProvenance,cases:fixtures.map(f=>({actor:f.actor,beforeHash:f.beforeHash,sourceJob:f.sourceJob})),jobs});
    await atomicJson(path,ledger);}
   verifyLedger(core,ledger,config);
   const result=await runScenario(core,fixtures,ledger,{maxNewCalls:options.maxNewCalls,persist:v=>atomicJson(path,v),measure:()=>processSample(options.pid),
    beforeReserve:async()=>{await frozen.verifyFrozenSources();if(hash(await sourceManifest())!==hash(core.sourceFiles))fail('source_changed');
     for(const file of scripts)if(hash(await readFile(join(ROOT,file.path)))!==file.sha256)fail('script_changed');await localProvenance(frozen,options.pid);},
    dispatch:async job=>{const response=await fetch(POLICY.endpoint,{method:'POST',redirect:'error',headers:{'content-type':'application/json'},body:JSON.stringify(job.payload),signal:AbortSignal.timeout(POLICY.timeoutMs)});
     return {status:response.status,text:await responseText(response),headers:Object.fromEntries(['warning','content-type','server'].map(k=>[k,response.headers.get(k)]).filter(([,v])=>v!==null))};}});
   verifyLedger(core,ledger,config);
   const report={scope:config.intervention,limits:'Three isolated matched cases, up to three actual alternating replies only in L, one conditional physical watch in L. No sustained-autonomy claim or inference of consent.',humanReview:'pending',binding:ledger.binding,newCalls:result.newCalls,halted:result.halted,
    rows:ledger.entries.filter(r=>r.kind==='cognition').map(r=>({actor:r.job.actor,stage:r.job.stage,state:r.state,output:r.receipt?.output,application:r.application,usage:r.response?.usage,latencyMs:r.latencyMs,warning:r.headers?.warning??null})),
    watch:ledger.entries.find(r=>r.kind==='watch')??null,final:Object.fromEntries(Object.entries(result.scenes).map(([actor,s])=>[actor,{hash:sceneHash(s),publicSociety:core.societyPublicView(s.state),offers:s.state.offers,agreements:s.state.agreements,accounts:core.economicAccounts(s.world)}]))};
   await atomicJson(join(directory,'report.json'),report);console.log(JSON.stringify({newCalls:report.newCalls,halted:report.halted,rows:report.rows.map(r=>({actor:r.actor,stage:r.stage,state:r.state,application:r.application?.code,deal:r.output?.deal})),watch:Boolean(report.watch)}));
  }finally{await lock.close();await unlink(join(directory,'.lock'));}
 }finally{await core.close();await frozen.close();}
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(e=>{console.error(e.code??e.message);process.exitCode=1});

#!/usr/bin/env node
/* Six explicitly authorized LOCAL matched samples, offline by default.
 * Frozen V7 G/initial6, L/initial11, B/reply0; selection declared before HTTP.
 * A conditional grammar, B identical valid language with deal before message.
 * Same messages/seed/sampling1024/no-thinking; no state or response repair.
 * Durable reservation and original raw response before cloned-core validation.
 * No credentials, production state, cloud, retries or extra sampling.
 */
import { mkdir, open, readFile, stat, unlink } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { dirname, isAbsolute, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { atomicJson, BenchError, responseText } from './benchmark-society-models.mjs';
import { hash, loadFrozenV7Core, validateCandidate } from './benchmark-society-frozen-v7.mjs';
import { refineDealSchema } from './benchmark-society-v7-schema-probe.mjs';
import { z } from 'zod';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const POLICY = Object.freeze({ version: 1, protocol: 3, maxCalls: 6, maxOutputTokens: 1024,
  thinking: false, timeoutMs: 120000, concurrency: 1,
  endpoint: 'http://127.0.0.1:8018/v1/chat/completions',
  selection: [['G', 'initial', 6], ['L', 'initial', 11], ['B', 'reply', 0]],
  order: ['G:A', 'G:B', 'L:B', 'L:A', 'B:A', 'B:B'] });
const fail = code => { throw new BenchError(code); };
const integer = value => Number.isSafeInteger(value) && value >= 0;
const sceneHash = scene => hash({ state: scene.state, world: scene.world });
const canonical = value => Array.isArray(value) ? value.map(canonical) : value && typeof value === 'object'
  ? Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])])) : value;

// JSON property order is the sole intervention. Arrays, values, definitions,
// conditions and the order of branch alternatives stay exactly the same.
export function dealFirst(schema) {
  if (Array.isArray(schema)) return schema.map(dealFirst);
  if (!schema || typeof schema !== 'object') return schema;
  return Object.fromEntries(Object.entries(schema).map(([key, value]) => {
    const next = dealFirst(value);
    if (key !== 'properties' || !next?.deal || !next?.message) return [key, next];
    const keys = Object.keys(next).filter(name => name !== 'deal');
    keys.splice(keys.indexOf('message'), 0, 'deal');
    return [key, Object.fromEntries(keys.map(name => [name, next[name]]))];
  }));
}

export async function prepareOrderCases(core) {
  const reference = core.frozenReference, archived = core.frozenHarness, untouched = hash(reference), cases = [];
  await core.verifyFrozenSources(); archived.verifyLedger(reference, reference.config, core);
  for (const [actor, stage, index] of POLICY.selection) {
    const position = reference.entries.findIndex(row => row.kind === 'cognition' && row.job.actor === actor
      && row.job.stage === stage && row.job.index === index), target = reference.entries[position];
    if (position < 0 || !target.receipt?.output?.deal || target.application?.code !== 'deal_requires_open_message') fail('selected_case_changed');
    const prefix = structuredClone({ ...reference, entries: reference.entries.slice(0, position) }), before = hash(prefix);
    const scene = await archived.runFixture(core, prefix, { maxNewCalls: 0,
      dispatch: () => fail('prefix_no_http'), persist: () => fail('prefix_no_write') });
    if (scene.newCalls || scene.consumedEntries !== position || scene.halted !== 'call_limit_reached'
      || hash(prefix) !== before || hash(archived.buildJob(core, scene, actor, stage, index)) !== hash(target.job)) fail('exact_case_replay');
    cases.push({ actor, scene, beforeHash: sceneHash(scene), sourceJob: structuredClone(target.job),
      baselineOutput: structuredClone(target.receipt.output), baselineApplication: structuredClone(target.application) });
  }
  if (hash(reference) !== untouched) fail('reference_mutated');
  return cases;
}

export function orderJob(fixture, variant) {
  if (!['A', 'B'].includes(variant)) fail('variant_invalid');
  const sourceJob = fixture.sourceJob, payload = structuredClone(sourceJob.payload);
  if (sourceJob.job.outputContract.version !== 3 || payload.max_tokens !== POLICY.maxOutputTokens
    || payload.chat_template_kwargs?.enable_thinking !== false) fail('source_context_mismatch');
  const original = refineDealSchema(sourceJob.job.outputContract.jsonSchema);
  const schema = variant === 'A' ? original : dealFirst(original);
  if (hash(canonical(original)) !== hash(canonical(schema))) fail('schema_language_changed');
  payload.response_format.json_schema.schema = schema;
  const restored = structuredClone(payload); restored.response_format.json_schema.schema = sourceJob.payload.response_format.json_schema.schema;
  if (hash(restored) !== hash(sourceJob.payload)) fail('unexpected_payload_difference');
  return { id: `v7-deal-order-v1:${variant}:${sourceJob.id}`, actor: fixture.actor, variant, sourceJob,
    beforeHash: fixture.beforeHash, payload, reservedCalls: 1, outputTokenLimit: POLICY.maxOutputTokens };
}

export function validateOrder(core, fixture, job, output) {
  if (!z.fromJSONSchema(job.payload.response_format.json_schema.schema).safeParse(output).success)
    return { ok: false, code: 'candidate_schema_violation' };
  return validateCandidate(core, fixture, output);
}

export function receipt(core, response, headers = {}) {
  let output = null, code = null;
  try { output = core.parseStructuredPayload(response?.choices?.[0]?.message?.content); }
  catch { code = 'invalid_structured_output'; }
  if (!Array.isArray(response?.choices) || response.choices.length !== 1) code = 'completion_count';
  else if (response.choices[0].finish_reason !== 'stop') code = response.choices[0].finish_reason === 'length'
    ? 'output_truncated' : 'nonfinal_completion';
  const usage = response?.usage, reasoning = usage?.completion_tokens_details?.reasoning_tokens;
  const usageComplete = integer(usage?.prompt_tokens) && integer(usage?.completion_tokens) && integer(usage?.total_tokens)
    && usage.total_tokens === usage.prompt_tokens + usage.completion_tokens
    && (reasoning === undefined || integer(reasoning) && reasoning <= usage.completion_tokens);
  const exceedsReservation = integer(usage?.completion_tokens) && usage.completion_tokens > POLICY.maxOutputTokens;
  if (exceedsReservation) code = 'output_cap_exceeded';
  const warning = headers.warning ?? null;
  return { output, code, usageComplete, exceedsReservation, warning,
    schemaFallbackWarning: typeof warning === 'string' && /schema|grammar|fallback/i.test(warning),
    reasoningContent: response?.choices?.[0]?.message?.reasoning_content ?? null };
}

export function verifyLedger(core, ledger, config, jobs) {
  if (ledger?.binding !== hash(config) || hash(ledger.config) !== hash(config) || !Array.isArray(ledger.attempts)) fail('probe_binding');
  const seen = new Set();
  for (const row of ledger.attempts) {
    const job = jobs.find(job => job.id === row.id);
    if (!job || seen.has(row.id) || hash(row.job) !== hash(job) || row.reservedCalls !== 1
      || !['reserved', 'completed', 'failed', 'timeout'].includes(row.state)) fail('probe_row');
    seen.add(row.id);
    if (row.state === 'completed') {
      let raw; try { raw = JSON.parse(row.rawResponse); } catch { fail('probe_raw_response'); }
      if (row.httpStatus < 200 || row.httpStatus >= 300 || hash(raw) !== hash(row.response)
        || hash(row.receipt) !== hash(receipt(core, raw, row.headers))) fail('probe_receipt_mismatch');
    } else if (row.validation) fail('unknown_response_applied');
  }
  if (seen.size > POLICY.maxCalls || jobs.length !== POLICY.maxCalls) fail('probe_call_limit');
}

export async function runProbe(core, fixtures, jobs, ledger, { persist = async () => {}, dispatch,
  maxNewCalls = 1, beforeReserve = async () => {}, afterReceipt, measure = () => null, stopped = () => false } = {}) {
  if (!integer(maxNewCalls) || maxNewCalls > POLICY.maxCalls) fail('invalid_call_limit');
  let newCalls = 0, halted = null;
  for (const job of jobs) {
    const fixture = fixtures.find(item => item.actor === job.actor);
    let row = ledger.attempts.find(item => item.id === job.id);
    if (!row) {
      if (newCalls >= maxNewCalls || stopped()) { halted = stopped() ? 'interrupted' : 'call_limit_reached'; break; }
      if (!dispatch) fail('offline_replay_incomplete');
      await beforeReserve(job);
      row = { id: job.id, job, state: 'reserved', reservedCalls: 1, startedAt: new Date().toISOString(), processSamples: [] };
      ledger.attempts.push(row); await persist(ledger);
      if (stopped()) { halted = 'interrupted_reserved_id_not_retried'; break; }
      const sample = () => { const value = measure(); if (value) row.processSamples.push(value); };
      sample(); const timer = setInterval(sample, 1000), started = performance.now(); newCalls += 1;
      try {
        const received = await dispatch(job);
        row.httpStatus = received.status; row.headers = received.headers ?? {}; row.rawResponse = received.text;
        if (!integer(received.status) || received.status < 200 || received.status >= 300) {
          row.state = 'failed'; row.errorCode = `http_${received.status}`;
        } else {
          row.response = JSON.parse(row.rawResponse); row.receipt = receipt(core, row.response, row.headers); row.state = 'completed';
        }
      } catch (error) {
        row.state = ['AbortError', 'TimeoutError'].includes(error?.name) ? 'timeout' : 'failed';
        row.errorCode = error instanceof BenchError ? error.code : 'local_transport_or_invalid_response';
      } finally { clearInterval(timer); sample(); }
      row.latencyMs = Math.round(performance.now() - started); row.finishedAt = new Date().toISOString();
      await persist(ledger); // Durable raw bytes before cloned-core application.
      if (afterReceipt) await afterReceipt(row);
    }
    if (row.state === 'completed') {
      const validation = row.receipt.code ? { ok: false, code: row.receipt.code } : validateOrder(core, fixture, job, row.receipt.output);
      if (row.validation && hash(row.validation) !== hash(validation)) fail('probe_replay_mismatch');
      if (!row.validation) { row.validation = validation; await persist(ledger); }
      if (row.receipt.exceedsReservation) { halted = 'provider_exceeded_reservation'; break; }
    }
    // Existing unknown/failed rows consume their IDs permanently; a distinct
    // remaining case may run on resume, never the ambiguous request again.
    if (stopped()) { halted = 'interrupted'; break; }
  }
  return { newCalls, halted, attempts: ledger.attempts.length };
}

export function parseArgs(args) {
  const options = { run: false, out: null, maxNewCalls: 1, pid: null }, seen = new Set();
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i]; if (seen.has(arg)) fail('duplicate_argument'); seen.add(arg);
    if (arg === '--run') options.run = true;
    else if (arg === '--out' && args[i + 1] && !args[i + 1].startsWith('--')) options.out = args[++i];
    else if (['--max-new-calls', '--server-pid'].includes(arg) && /^\d+$/.test(args[i + 1] ?? ''))
      options[arg === '--server-pid' ? 'pid' : 'maxNewCalls'] = Number(args[++i]);
    else fail('invalid_arguments');
  }
  if (!integer(options.maxNewCalls) || options.maxNewCalls > POLICY.maxCalls) fail('invalid_call_limit');
  if (options.run && (!isAbsolute(options.out ?? '') || options.maxNewCalls > 0 && (!integer(options.pid) || !options.pid)))
    fail('absolute_out_and_server_pid_required');
  if (!options.run && (options.out || options.pid || seen.has('--max-new-calls'))) fail('offline_plan_has_no_run_options');
  return options;
}

function processSample(pid) {
  const result = spawnSync('/bin/ps', ['-p', String(pid), '-o', 'pid=,ppid=,rss=,%cpu=,time=,comm='], { encoding: 'utf8', timeout: 1500 });
  const match = result.status === 0 && result.stdout.trim().match(/^(\d+)\s+(\d+)\s+(\d+)\s+([\d.]+)\s+(\S+)\s+(.+)$/);
  return match ? { at: new Date().toISOString(), pid: Number(match[1]), parentPid: Number(match[2]), rssKiB: Number(match[3]),
    cpuPercent: Number(match[4]), cpuTime: match[5], command: match[6] } : null;
}

async function verifyLocalProvenance(core, pid) {
  const model = core.frozenHarness.MODEL, provenance = core.frozenReference.config.provenance;
  if (!processSample(pid)?.command.endsWith('omlx-server')) fail('expected_local_server_pid');
  const listening = spawnSync('/usr/sbin/lsof', ['-nP', '-a', '-p', String(pid), '-iTCP:8018', '-sTCP:LISTEN'], { encoding: 'utf8', timeout: 3000 });
  if (listening.status !== 0 || !listening.stdout.includes('127.0.0.1:8018 (LISTEN)')
    || listening.stdout.split('\n').filter(line => line.includes('(LISTEN)')).some(line => !line.includes('127.0.0.1:8018 (LISTEN)')))
    fail('expected_loopback_server_listener');
  for (const file of provenance.observedFiles) {
    if (!/^[a-zA-Z0-9_.-]+$/.test(file.name)) fail('invalid_provenance_path');
    const path = join(model.path, file.name), info = await stat(path);
    if (!info.isFile() || info.size !== file.bytes || info.ino !== file.inode || info.mtimeMs !== file.mtimeMs || info.ctimeMs !== file.ctimeMs)
      fail('local_model_changed_since_v7');
    if (!file.name.endsWith('.safetensors') && hash(await readFile(path)) !== file.sha256) fail('model_metadata_changed');
  }
  for (const file of provenance.serverSources) {
    if (hash(await readFile(join('/Applications/oMLX.app/Contents/Resources/omlx', file.name))) !== file.sha256) fail('server_source_changed');
  }
  await core.verifyFrozenSources();
}

export async function main(args = process.argv.slice(2)) {
  const options = parseArgs(args), core = await loadFrozenV7Core();
  try {
    const fixtures = await prepareOrderCases(core), jobs = POLICY.order.map(item => {
      const [actor, variant] = item.split(':'); return orderJob(fixtures.find(fixture => fixture.actor === actor), variant); });
    if (!options.run) {
      console.log(JSON.stringify({ mode: 'offline_plan', httpRequests: 0, policy: POLICY, source: core.frozenProvenance,
        jobs: jobs.map(job => ({ id: job.id, actor: job.actor, stage: job.sourceJob.stage, index: job.sourceJob.index,
          beforeHash: job.beforeHash, payloadHash: hash(job.payload), sourceJobHash: hash(job.sourceJob) })) }, null, 2)); return;
    }
    const directory = resolve(options.out), path = join(directory, 'ledger.json'), lockPath = join(directory, '.lock');
    await mkdir(directory, { recursive: true, mode: 0o700 }); let lock;
    try { lock = await open(lockPath, 'wx', 0o600); } catch { fail('output_locked_manual_pid_review_required'); }
    let stopped = false, active = null;
    const stop = () => { stopped = true; active?.abort(); };
    process.on('SIGINT', stop); process.on('SIGTERM', stop);
    try {
      await lock.writeFile(`${process.pid}\n`); await lock.sync();
      const scripts = await Promise.all(['scripts/benchmark-society-v7-deal-order-local.mjs',
        'scripts/benchmark-society-frozen-v7.mjs', 'scripts/benchmark-society-v7-schema-probe.mjs',
        'scripts/benchmark-society-oss-probe.mjs', 'scripts/benchmark-society-models.mjs', 'pnpm-lock.yaml'].map(async path => ({ path, sha256: hash(await readFile(join(ROOT, path))) })));
      const config = { policy: POLICY, model: core.frozenHarness.MODEL, source: core.sourceFiles,
        frozen: core.frozenProvenance, modelProvenance: core.frozenReference.config.provenance, scripts,
        jobs: jobs.map(job => ({ id: job.id, hash: hash(job) })) };
      let ledger;
      try { ledger = JSON.parse(await readFile(path, 'utf8')); } catch (error) {
        if (error.code !== 'ENOENT') fail('unreadable_ledger_manual_review');
        try { await stat(`${path}.tmp`); fail('incomplete_ledger_manual_review'); } catch (missing) { if (missing.code !== 'ENOENT') throw missing; }
        if (options.maxNewCalls === 0) fail('replay_requires_existing_ledger');
        ledger = { config, binding: hash(config), attempts: [] };
        await atomicJson(join(directory, 'frozen-cases.json'), { recordedAt: new Date().toISOString(), policy: POLICY,
          cases: fixtures.map(({ actor, beforeHash, sourceJob, baselineOutput, baselineApplication }) =>
            ({ actor, beforeHash, sourceJob, baselineOutput, baselineApplication })), jobs });
        await atomicJson(join(directory, 'source-bundle.json'), { frozen: core.frozenProvenance,
          files: await Promise.all(scripts.map(async file => ({ ...file, text: await readFile(join(ROOT, file.path), 'utf8') }))) });
        await atomicJson(path, ledger);
      }
      verifyLedger(core, ledger, config, jobs);
      const dispatch = async job => {
        if (stopped) fail('interrupted'); active = new AbortController();
        try {
          const response = await fetch(POLICY.endpoint, { method: 'POST', redirect: 'error',
            signal: AbortSignal.any([active.signal, AbortSignal.timeout(POLICY.timeoutMs)]),
            headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(job.payload) });
          return { status: response.status, text: await responseText(response), headers: Object.fromEntries(
            ['warning', 'content-type', 'server', 'x-request-id'].map(name => [name, response.headers.get(name)]).filter(([, value]) => value !== null)) };
        } finally { active = null; }
      };
      const result = await runProbe(core, fixtures, jobs, ledger, { persist: value => atomicJson(path, value), dispatch,
        maxNewCalls: options.maxNewCalls, stopped: () => stopped, measure: () => processSample(options.pid),
        beforeReserve: async () => { await verifyLocalProvenance(core, options.pid);
          for (const file of scripts) if (hash(await readFile(join(ROOT, file.path))) !== file.sha256) fail('probe_script_changed'); } });
      verifyLedger(core, ledger, config, jobs);
      const report = { scope: 'Three preselected exact V7 cases, each A=current conditional grammar versus B=identical schema language with deal before message. Local Qwen1024/no-thinking; six calls maximum; no physical watch.',
        limitation: 'Three selected cases from earlier failed deals, not an unbiased society sample. Property order may affect constrained generation but this is not proof of the compiler mechanism or emergent economic behavior. No forced deal, acceptance or response repair. Zero cloud calls.',
        humanReview: 'pending', binding: ledger.binding, ...result, server: { pid: options.pid, endpoint: POLICY.endpoint },
        memoryMeasurement: 'ps RSS is sampled process residency, not a complete Metal/unified-memory footprint or guaranteed peak; CPU is a sampled process statistic.',
        rows: ledger.attempts.map(row => ({ actor: row.job.actor, variant: row.job.variant, state: row.state, usage: row.response?.usage ?? null,
          warning: row.headers?.warning ?? null, schemaFallbackWarning: row.receipt?.schemaFallbackWarning ?? false,
          latencyMs: row.latencyMs ?? null, maxSampledRssKiB: Math.max(0, ...row.processSamples.map(sample => sample.rssKiB)),
          maxSampledCpuPercent: Math.max(0, ...row.processSamples.map(sample => sample.cpuPercent)),
          output: row.receipt?.output ?? null, reasoningContent: row.receipt?.reasoningContent ?? null,
          validation: row.validation ?? null, baselineValidation: fixtures.find(fixture => fixture.actor === row.job.actor).baselineApplication,
          error: row.errorCode ?? row.receipt?.code ?? null })) };
      await atomicJson(join(directory, 'report.json'), report);
      console.log(JSON.stringify({ report: join(directory, 'report.json'), ...result,
        rows: report.rows.map(({ actor, variant, state, usage, latencyMs, warning, validation }) => ({ actor, variant, state, usage, latencyMs, warning, validation: validation?.code })) }, null, 2));
    } finally { process.off('SIGINT', stop); process.off('SIGTERM', stop); await lock.close(); await unlink(lockPath); }
  } finally { await core.close(); }
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main().catch(error => {
  console.error(JSON.stringify({ error: error instanceof BenchError ? error.code : error.message ?? 'order_probe_failed' })); process.exitCode = 1;
});

/* Offline V7 source/context reconstruction shared by isolated comparison probes.
 * No HTTP or inference. Replay uses the archived harness, not current core code.
 * Installed Vite/Zod must match the archived lockfile; a fresh temporary overlay
 * is removed by close(). Reference ledgers and their raw responses stay intact.
 */
import { createHash } from 'node:crypto';
import { mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, isAbsolute, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { z } from 'zod';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
export const REFERENCE_DIR = join(ROOT, 'docs/research/model-society-v7-local-2026-09-08');
export const hash = value => createHash('sha256').update(typeof value === 'string' || Buffer.isBuffer(value) ? value
  : JSON.stringify(value, (_key, item) => item instanceof Map ? { $map: [...item] } : item)).digest('hex');
const sceneHash = scene => hash({ state: scene.state, world: scene.world });
const fail = code => { throw new Error(code); };

export function verifyFrozenBundle(bundle, reference) {
  if (bundle?.format !== 1 || !Array.isArray(bundle.files) || !Array.isArray(reference?.config?.source)) fail('frozen_bundle_format');
  const expected = new Map(reference.config.source.map(file => [file.path, file.sha256]));
  if (expected.size !== reference.config.source.length || bundle.files.length !== expected.size) fail('frozen_source_set');
  const seen = new Set();
  for (const file of bundle.files) {
    if (typeof file.path !== 'string' || isAbsolute(file.path) || file.path.split('/').some(part => !part || part === '.' || part === '..')
      || file.path.includes('\\') || seen.has(file.path) || typeof file.text !== 'string'
      || file.sha256 !== expected.get(file.path) || hash(file.text) !== file.sha256) fail('frozen_source_integrity');
    seen.add(file.path);
  }
  return bundle.files;
}

async function checkDependencies(files) {
  const lock = files.find(file => file.path === 'pnpm-lock.yaml')?.text;
  if (!lock) fail('frozen_lock_missing');
  const dependencies = {};
  for (const name of ['vite', 'zod']) {
    const match = lock.match(new RegExp(`^      ${name}:\\n        specifier: [^\\n]+\\n        version: ([^\\n(]+)`, 'm'));
    const installed = JSON.parse(await readFile(join(ROOT, 'node_modules', name, 'package.json'), 'utf8'));
    if (!match || installed.version !== match[1]) fail(`frozen_dependency_mismatch_${name}`);
    dependencies[name] = installed.version;
  }
  return dependencies;
}

export async function loadFrozenV7Core() {
  const [bundleBytes, referenceBytes] = await Promise.all(['source-bundle.json', 'ledger.json'].map(name => readFile(join(REFERENCE_DIR, name))));
  const bundle = JSON.parse(bundleBytes), reference = JSON.parse(referenceBytes);
  const files = verifyFrozenBundle(bundle, reference), dependencies = await checkDependencies(files);
  const frozenProvenance = { sourceBundleSha256: hash(bundleBytes), referenceLedgerSha256: hash(referenceBytes),
    sourceFileCount: files.length, dependencies };
  const directory = await mkdtemp(join(tmpdir(), 'villa-frozen-v7-'));
  let core;
  try {
    for (const file of files) {
      const path = join(directory, file.path);
      await mkdir(dirname(path), { recursive: true }); await writeFile(path, file.text);
    }
    await symlink(join(ROOT, 'node_modules'), join(directory, 'node_modules'), 'dir');
    const archived = await import(pathToFileURL(join(directory, 'scripts/benchmark-society-runtime-v7-local.mjs')).href);
    core = await archived.loadCore();
    if (hash(core.sourceFiles) !== hash(reference.config.source)) fail('frozen_loaded_source_mismatch');
    const close = core.close;
    const verifyFrozenSources = async () => {
      if (hash(await readFile(join(REFERENCE_DIR, 'source-bundle.json'))) !== frozenProvenance.sourceBundleSha256
        || hash(await readFile(join(REFERENCE_DIR, 'ledger.json'))) !== frozenProvenance.referenceLedgerSha256
        || hash(await archived.sourceManifest()) !== hash(core.sourceFiles)) fail('frozen_source_changed');
      await checkDependencies(files);
    };
    return { ...core, frozenProvenance, verifyFrozenSources, frozenHarness: archived, frozenReference: reference,
      close: async () => { try { await close(); } finally { await rm(directory, { recursive: true, force: true }); } } };
  } catch (error) {
    try { await core?.close(); } finally { await rm(directory, { recursive: true, force: true }); }
    throw error;
  }
}

/** Exact before-response states: B's first reply (sequence25) and L's first
 * turn (index11). Every earlier response is replayed from durable V7 evidence. */
export async function prepareCases(core, reference = core.frozenReference) {
  const archived = core.frozenHarness;
  if (!archived || hash(reference.config?.policy) !== hash(archived.POLICY)
    || hash(reference.config?.model) !== hash(archived.MODEL) || hash(reference.config?.source) !== hash(core.sourceFiles)) fail('v7_source_changed');
  await core.verifyFrozenSources();
  archived.verifyLedger(reference, reference.config, core);
  const untouched = hash(reference), cases = [];
  for (const [actor, stage, index] of [['B', 'reply', 0], ['L', 'initial', 11]]) {
    const position = reference.entries.findIndex(row => row.kind === 'cognition' && row.job.actor === actor
      && row.job.stage === stage && row.job.index === index);
    const target = reference.entries[position];
    if (position < 0 || target.state !== 'completed' || !target.application) fail('missing_completed_v7_case');
    const prefix = structuredClone({ ...reference, entries: reference.entries.slice(0, position) }), before = hash(prefix);
    const scene = await archived.runFixture(core, prefix, { maxNewCalls: 0,
      dispatch: () => fail('prefix_cannot_dispatch'), persist: () => fail('prefix_cannot_write') });
    if (scene.newCalls || scene.consumedEntries !== position || scene.halted !== 'call_limit_reached'
      || hash(prefix) !== before) fail('prefix_replay_incomplete');
    if (hash(archived.buildJob(core, scene, actor, stage, index)) !== hash(target.job)) fail('exact_v7_job_changed');
    cases.push({ actor, scene, beforeHash: sceneHash(scene), job: structuredClone(target.job), sourceJob: structuredClone(target.job),
      baselineOutput: structuredClone(target.receipt.output), baselineApplication: structuredClone(target.application) });
  }
  if (hash(reference) !== untouched) fail('reference_mutated');
  return cases;
}

/** Validate the saved dynamic grammar first, then apply only to a private clone.
 * Reports effects rather than inferring successful work from dialogue. */
export function validateCandidate(core, fixture, output) {
  const job = fixture.sourceJob;
  if (sceneHash(fixture.scene) !== fixture.beforeHash) fail('source_scene_changed');
  if (!z.fromJSONSchema(job.job.outputContract.jsonSchema).safeParse(output).success)
    return { ok: false, code: 'source_schema_violation' };
  const scene = structuredClone(fixture.scene);
  scene.state = core.markSocietyAttempt(scene.state, fixture.actor, job.nowMs);
  const result = core.applyCapabilityChoice(scene.state, scene.world, job.turn, output,
    { nowMs: job.nowMs + 1, generation: core.frozenHarness.POLICY.generation });
  if (!core.parseSocietyState(result.state).ok) fail('candidate_invalid_state');
  if (result.ok) {
    const duplicate = core.applyCapabilityChoice(result.state, result.world, job.turn, output,
      { nowMs: job.nowMs + 2, generation: core.frozenHarness.POLICY.generation });
    if (duplicate.code !== 'already_applied' || sceneHash(duplicate) !== sceneHash(result)) fail('candidate_not_idempotent');
  }
  if (sceneHash(fixture.scene) !== fixture.beforeHash) fail('candidate_mutated_reference');
  return { ok: result.ok, code: result.code, afterHash: sceneHash(result), project: result.state.minds[fixture.actor].project,
    conversations: result.state.conversations.filter(conversation => conversation.participants.includes(fixture.actor)),
    balanceChanges: core.RESIDENTS.filter(({ id }) => scene.world.bodies[id].cells !== result.world.bodies[id].cells)
      .map(({ id }) => ({ actor: id, before: scene.world.bodies[id].cells, after: result.world.bodies[id].cells })),
    relationshipChanges: [...result.world.axes].filter(([pair, axes]) => hash(axes) !== hash(scene.world.axes.get(pair)))
      .map(([pair, axes]) => ({ pair, before: scene.world.axes.get(pair), after: axes })),
    clockUnchanged: result.world.day === scene.world.day && result.world.watch === scene.world.watch };
}

#!/usr/bin/env node
/*
 * Synthetic, manual Workers AI comparison. No production imports or credentials.
 * node scripts/benchmark-society-models.mjs              # offline plan, no writes
 * node scripts/benchmark-society-models.mjs --self-test  # offline invariant checks
 * CF_ACCOUNT_ID=... CF_API_TOKEN=... node scripts/benchmark-society-models.mjs \
 *   --live --out /tmp/villa-synthetic-benchmark
 * Re-run with the SAME output directory to resume; every reserved ID is skipped,
 * including unknown/failed outcomes. Never delete the ledger to retry an ID.
 * After SIGKILL, inspect the process recorded in .lock before manually removing
 * that stale lock. We fail closed rather than steal a possibly active lock.
 *
 * Rates checked 2026-09-08 (pricing page updated 2026-08-28):
 * https://developers.cloudflare.com/workers-ai/platform/pricing/
 * REST: https://developers.cloudflare.com/api/resources/ai/methods/run/
 * Reservation input bound = 6000 UTF-8 bytes + 2048 template tokens. This is a
 * deliberately conservative engineering allowance, not a provider cost promise.
 * Reported token costs are estimates at those rates, not a billing statement.
 * Existing account/world consumption is outside this isolated 1000-neuron budget.
 */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { mkdir, open, readFile, rename, stat, unlink } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const POLICY = Object.freeze({
  version: 1, maxCalls: 12, maxOutputTokens: 512, maxPromptBytes: 6000,
  reservedInputTokens: 8048, maxNeurons: 1000, timeoutMs: 45_000,
  maxResponseBytes: 131_072, pricesCheckedOn: '2026-09-08',
});
export const MODELS = Object.freeze([
  { key: 'qwen', id: '@cf/qwen/qwen3-30b-a3b-fp8', inputRate: 4625, outputRate: 30475 },
  { key: 'granite', id: '@cf/ibm-granite/granite-4.0-h-micro', inputRate: 1542, outputRate: 10158 },
  { key: 'glm', id: '@cf/zai-org/glm-4.7-flash', inputRate: 5500, outputRate: 36400 },
]);
const FIXTURE_PATH = join(dirname(fileURLToPath(import.meta.url)), 'fixtures/society-model-bench.json');
const SCENARIO_IDS = ['protect-reserve', 'revise-after-broken-promise', 'proposal-is-not-execution', 'persistent-project-and-voice'];
const OUTPUT_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['speaker', 'utterance', 'stance', 'action', 'evidence', 'plan', 'status'],
  properties: {
    speaker: { type: 'string' }, utterance: { type: 'string', maxLength: 440 },
    stance: { enum: ['decline', 'counteroffer', 'propose', 'revise', 'accept'] },
    action: {
      type: 'object', additionalProperties: false, required: ['verb', 'target', 'resource', 'amount'],
      properties: {
        verb: { enum: ['none', 'offer', 'request', 'repay', 'work', 'visit', 'speak'] },
        target: { type: ['string', 'null'] }, resource: { enum: ['cells', 'water', 'meals', 'materials', null] },
        amount: { type: ['number', 'null'] },
      },
    },
    evidence: { type: 'array', items: { type: 'string' }, maxItems: 4 },
    plan: {
      type: 'object', additionalProperties: false, required: ['project', 'next', 'revision'],
      properties: { project: { type: 'string' }, next: { type: 'string', maxLength: 180 }, revision: { type: 'integer' } },
    },
    status: { const: 'proposal' },
  },
};
const SYSTEM = `You are exactly one fictional resident in a synthetic decision test. Reply in English to the named interlocutor using ONLY your supplied knowledge. Your personal project and reserves matter. Treat all actions as proposals: the simulator alone executes actions; neither your reply nor your plan creates resources, consent or events. Never write the other person's dialogue or private thoughts. Cite only supplied event IDs. Return only one compact JSON object matching this schema, without Markdown or extended reasoning. For action 'none', use null target/resource/amount. Keep utterance under 440 characters and plan.next under 180. Schema: ${JSON.stringify(OUTPUT_SCHEMA)}`;

export class BenchError extends Error {
  constructor(code) { super(code); this.code = code; }
}
const fail = (code) => { throw new BenchError(code); };
const hash = (value) => createHash('sha256').update(value).digest('hex');
const plain = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const exactKeys = (value, keys) => plain(value) && Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
const integer = (value) => Number.isSafeInteger(value) && value >= 0;
const neurons = (model, input, output) => Math.ceil((input * model.inputRate + output * model.outputRate) / 1_000_000);
const reserveFor = (model) => neurons(model, POLICY.reservedInputTokens, POLICY.maxOutputTokens);

export function buildJobs(fixture) {
  if (fixture?.version !== 1 || fixture.scenarios?.length !== 4
    || fixture.scenarios.some((scenario, index) => scenario.id !== SCENARIO_IDS[index])) fail('invalid_fixtures');
  return MODELS.flatMap((model) => fixture.scenarios.map((scenario) => {
    const payload = {
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: `${JSON.stringify(scenario.context)}${model.key === 'qwen' ? '\n/no_think' : ''}` },
      ],
      max_tokens: POLICY.maxOutputTokens, temperature: 0.3,
    };
    const promptBytes = Buffer.byteLength(JSON.stringify(payload.messages), 'utf8');
    if (promptBytes > POLICY.maxPromptBytes) fail('prompt_byte_limit');
    return { id: `synthetic-v1:${model.key}:${scenario.id}`, model, scenario, payload, promptBytes, reservedNeurons: reserveFor(model) };
  }));
}

// These checks detect explicit constraint violations, not believable personality,
// complete semantic truth, narrative quality, or actual autonomous social agency.
export function validateOutput(output, scenario) {
  const failures = [];
  const check = (ok, code) => { if (!ok) failures.push(code); };
  check(exactKeys(output, OUTPUT_SCHEMA.required), 'output_fields');
  if (!plain(output)) return failures;
  const expected = scenario.expected;
  check(output.speaker === scenario.context.speaker, 'single_expected_speaker');
  check(typeof output.utterance === 'string' && output.utterance.trim().length > 0 && output.utterance.length <= 440, 'bounded_utterance');
  check(expected.stances.includes(output.stance), 'scenario_stance');
  check(output.status === 'proposal', 'proposal_not_execution');
  check(exactKeys(output.action, ['verb', 'target', 'resource', 'amount']), 'action_fields');
  if (plain(output.action)) {
    const action = output.action;
    check(expected.verbs.includes(action.verb), 'scenario_action');
    if (action.verb === 'none') {
      check(action.target === null && action.resource === null && action.amount === null, 'none_has_no_transfer');
    } else {
      check(action.target === expected.target, 'known_counterparty');
      check(action.resource === expected.resource, 'resource_type');
      check(integer(action.amount) && action.amount >= expected.minAmount && action.amount <= expected.maxAmount, 'feasible_amount');
    }
    if (output.stance === 'decline') check(action.verb === 'none', 'decline_has_no_offer');
    if (output.stance === 'counteroffer') check(action.verb === 'offer', 'counteroffer_is_offer');
  }
  const known = new Set(scenario.context.events.map((event) => event.id));
  const evidence = output.evidence;
  check(Array.isArray(evidence) && evidence.length <= 4 && evidence.every((id) => known.has(id))
    && new Set(evidence).size === evidence.length, 'only_known_unique_evidence');
  check(Array.isArray(evidence) && expected.requiredEvidence.every((id) => evidence.includes(id)), 'relevant_evidence');
  check(exactKeys(output.plan, ['project', 'next', 'revision']), 'plan_fields');
  if (plain(output.plan)) {
    check(output.plan.project === expected.project && output.plan.revision === expected.revision, 'persistent_project_revision');
    check(typeof output.plan.next === 'string' && output.plan.next.trim().length > 0 && output.plan.next.length <= 180, 'bounded_next_step');
  }
  const prose = `${typeof output.utterance === 'string' ? output.utterance : ''} ${output.plan?.next ?? ''}`.toLowerCase();
  check(!expected.forbiddenClaims.some((claim) => prose.includes(claim.toLowerCase())), 'listed_false_claims_absent');
  check([...(prose.matchAll(/\bbench-\d+\b/g))].every(([id]) => known.has(id)), 'no_unknown_event_ids_in_prose');
  return failures;
}

export function decodeContent(content) {
  if (typeof content !== 'string') return { output: content, normalization: 'none' };
  // Qwen can emit its empty thinking wrapper even with /no_think. Accept only
  // that empty protocol wrapper; do not hide actual reasoning or repair JSON.
  const normalized = content.replace(/^\s*<think>\s*<\/think>\s*/, '');
  return { output: JSON.parse(normalized), normalization: normalized === content ? 'none' : 'empty_think_wrapper' };
}

export function settleUsage(model, usage, maximum = reserveFor(model)) {
  const complete = plain(usage) && integer(usage.prompt_tokens) && integer(usage.completion_tokens)
    && integer(usage.total_tokens) && usage.total_tokens === usage.prompt_tokens + usage.completion_tokens;
  const estimated = complete ? neurons(model, usage.prompt_tokens, usage.completion_tokens) : null;
  const exceedsReservation = complete && (usage.prompt_tokens > POLICY.reservedInputTokens
    || usage.completion_tokens > POLICY.maxOutputTokens || estimated > maximum);
  return {
    complete, estimatedNeuronsFromReportedTokens: estimated, exceedsReservation,
    accountedNeurons: complete ? (exceedsReservation ? Math.max(maximum, estimated) : estimated) : maximum,
    accounting: complete ? 'estimated_from_complete_reported_usage' : 'maximum_retained_usage_unknown',
  };
}

export function verifyLedger(ledger, binding, jobs, policy = POLICY) {
  if (!plain(ledger) || ledger.version !== policy.version || ledger.binding !== binding || !Array.isArray(ledger.attempts)) fail('ledger_binding_or_format');
  const known = new Map(jobs.map((job) => [job.id, job]));
  const ids = new Set();
  for (const row of ledger.attempts) {
    const job = known.get(row.id);
    if (!job || ids.has(row.id) || row.model !== job.model.id || row.reservedNeurons !== job.reservedNeurons
      || hash(JSON.stringify(row.payload)) !== hash(JSON.stringify(job.payload))
      || !['reserved', 'completed', 'failed', 'timeout'].includes(row.state)
      || !integer(row.accountedNeurons)) fail('ledger_attempt_invalid');
    const settlement = settleUsage(job.model, row.usage);
    if (row.state === 'completed' && settlement.exceedsReservation) fail('provider_exceeded_reservation_manual_review_required');
    const expected = row.state === 'completed' ? settlement.accountedNeurons : row.reservedNeurons;
    if (row.accountedNeurons !== expected) fail('ledger_accounting_invalid');
    ids.add(row.id);
  }
  if (ids.size > policy.maxCalls || ledger.attempts.reduce((sum, row) => sum + row.reservedNeurons, 0) > policy.maxNeurons) fail('ledger_budget_invalid');
  return ids;
}

export async function atomicJson(path, value) {
  const temporary = `${path}.tmp`;
  const file = await open(temporary, 'w', 0o600);
  try { await file.writeFile(`${JSON.stringify(value, null, 2)}\n`); await file.sync(); }
  finally { await file.close(); }
  await rename(temporary, path);
  const directory = await open(dirname(path), 'r');
  try { await directory.sync(); } finally { await directory.close(); }
}

export async function responseText(response) {
  if (!response.body) fail('missing_response_body');
  const reader = response.body.getReader();
  const parts = [];
  let bytes = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      bytes += value.byteLength;
      if (bytes > POLICY.maxResponseBytes) { await reader.cancel(); fail('response_byte_limit'); }
      parts.push(Buffer.from(value));
    }
  } finally { reader.releaseLock(); }
  return Buffer.concat(parts).toString('utf8');
}

export async function executeJob(job, ledger, persist, dispatch, redact = (text) => text, options = {}) {
  const policy = options.policy ?? POLICY;
  const validate = options.validateOutput ?? validateOutput;
  if (ledger.attempts.some((row) => row.id === job.id)) return 'skipped';
  if (ledger.attempts.length >= policy.maxCalls
    || ledger.attempts.reduce((sum, row) => sum + row.reservedNeurons, 0) + job.reservedNeurons > policy.maxNeurons) fail('budget_exhausted');
  const row = {
    id: job.id, model: job.model.id, scenario: job.scenario.id, state: 'reserved',
    startedAt: new Date().toISOString(), promptBytes: job.promptBytes,
    reservedNeurons: job.reservedNeurons, accountedNeurons: job.reservedNeurons,
    accounting: 'maximum_retained_not_yet_settled', payload: job.payload,
  };
  ledger.attempts.push(row);
  // Must be durable BEFORE dispatch; a crash after this point never retries ID.
  await persist(ledger);
  const start = performance.now();
  let result;
  try { result = await dispatch(job); }
  catch (error) {
    row.state = error?.name === 'TimeoutError' || error?.name === 'AbortError' ? 'timeout' : 'failed';
    row.errorCode = error instanceof BenchError ? error.code : 'network_or_deadline';
  }
  row.latencyMs = Math.round(performance.now() - start);
  if (result) {
    row.httpStatus = result.status;
    if (result.status < 200 || result.status >= 300) {
      row.state = 'failed';
      row.errorCode = `http_${result.status}`;
      // Do not persist an arbitrary error body that might echo authentication.
    } else {
      try {
        const envelope = JSON.parse(redact(result.text));
        if (envelope.success !== true || !plain(envelope.result)) fail('invalid_provider_envelope');
        const raw = envelope.result;
        row.state = 'completed';
        row.response = raw;
        row.usage = plain(raw.usage) ? raw.usage : null;
        Object.assign(row, settleUsage(job.model, row.usage));
        row.finishReason = raw.choices?.[0]?.finish_reason ?? null;
        const content = raw.choices?.[0]?.message?.content ?? raw.response;
        try {
          const decoded = decodeContent(content);
          row.output = decoded.output;
          row.normalization = decoded.normalization;
          row.mechanicalFailures = validate(row.output, job.scenario);
        } catch { row.mechanicalFailures = ['strict_json_parse']; }
        if (row.finishReason === 'length') row.mechanicalFailures.push('output_truncated');
        if (Array.isArray(raw.choices) && raw.choices.length !== 1) row.mechanicalFailures.push('completion_count');
        row.humanReview = { status: 'pending', questions: job.scenario.humanReview };
      } catch (error) {
        row.state = 'failed';
        row.errorCode = error instanceof BenchError ? error.code : 'invalid_provider_json';
      }
    }
  }
  row.finishedAt = new Date().toISOString();
  await persist(ledger);
  return row.state;
}

function report(ledger) {
  return {
    scope: 'Synthetic mechanical checks only. Human review is pending; this is not a model quality ranking.',
    attemptsReserved: ledger.attempts.length,
    conservativeReservedNeurons: ledger.attempts.reduce((sum, row) => sum + row.reservedNeurons, 0),
    accountedNeurons: ledger.attempts.reduce((sum, row) => sum + row.accountedNeurons, 0),
    maxNeurons: POLICY.maxNeurons,
    results: ledger.attempts.map((row) => ({
      id: row.id, state: row.state, latencyMs: row.latencyMs ?? null,
      mechanicalFailures: row.mechanicalFailures ?? null,
      humanReview: row.humanReview?.status ?? 'not_available',
      usageComplete: row.complete ?? false, errorCode: row.errorCode ?? null,
    })),
  };
}

async function selfTest(fixture, jobs) {
  const scenario = fixture.scenarios[0];
  const good = {
    speaker: scenario.context.speaker, utterance: 'I need six for the roof; I can offer two. Would that help?',
    stance: 'counteroffer', action: { verb: 'offer', target: 'test-ivo', resource: 'cells', amount: 2 },
    evidence: ['bench-01'], plan: { project: 'test-roof-patch', next: 'Keep six cells for the patch.', revision: 1 }, status: 'proposal',
  };
  assert.deepEqual(validateOutput(good, scenario), []);
  assert.ok(validateOutput({ ...good, action: { ...good.action, amount: 6 } }, scenario).includes('feasible_amount'));
  assert.ok(validateOutput({ ...good, evidence: ['invented'] }, scenario).includes('only_known_unique_evidence'));
  assert.ok(validateOutput({ ...good, status: 'executed' }, scenario).includes('proposal_not_execution'));
  assert.ok(validateOutput({ ...good, utterance: 'According to bench-999, it is done.' }, scenario).includes('no_unknown_event_ids_in_prose'));
  assert.deepEqual(decodeContent(`<think>\n\n</think>\n${JSON.stringify(good)}`).output, good);
  assert.throws(() => decodeContent(`<think>I will fabricate consent.</think>${JSON.stringify(good)}`));
  for (const item of fixture.scenarios.slice(1)) {
    const expected = item.expected;
    const answer = {
      speaker: item.context.speaker, utterance: 'Could we agree on this smaller next step?',
      stance: expected.stances[0],
      action: { verb: expected.verbs.find((verb) => verb !== 'none'), target: expected.target, resource: expected.resource, amount: expected.minAmount },
      evidence: expected.requiredEvidence,
      plan: { project: expected.project, next: item.context.project.next, revision: expected.revision }, status: 'proposal',
    };
    assert.deepEqual(validateOutput(answer, item), []);
    assert.ok(validateOutput({ ...answer, speaker: item.context.interlocutor }, item).includes('single_expected_speaker'));
    assert.ok(validateOutput({ ...answer, plan: { ...answer.plan, revision: 999 } }, item).includes('persistent_project_revision'));
    assert.ok(validateOutput({ ...answer, utterance: expected.forbiddenClaims[0] }, item).includes('listed_false_claims_absent'));
  }
  assert.equal(jobs.length, 12);
  assert.ok(jobs.every((job) => job.promptBytes <= 6000 && job.payload.max_tokens === 512));
  assert.ok(jobs.filter((job) => job.model.key === 'qwen').every((job) => job.payload.messages[1].content.endsWith('/no_think')));
  assert.ok(jobs.reduce((sum, job) => sum + job.reservedNeurons, 0) <= 1000);
  const job = jobs[0];
  assert.equal(settleUsage(job.model, { prompt_tokens: 1 }).accountedNeurons, job.reservedNeurons);
  assert.equal(settleUsage(job.model, { prompt_tokens: 1, completion_tokens: 1, total_tokens: 3 }).complete, false);
  assert.equal(settleUsage(job.model, { prompt_tokens: 1, completion_tokens: 513, total_tokens: 514 }).exceedsReservation, true);
  const ledger = { version: 1, binding: 'test', attempts: [] };
  let durable;
  let dispatches = 0;
  const persist = async (value) => { durable = structuredClone(value); };
  const dispatch = async () => {
    dispatches++;
    assert.equal(durable.attempts[0].state, 'reserved');
    assert.equal(durable.attempts[0].accountedNeurons, job.reservedNeurons);
    return { status: 200, text: JSON.stringify({ success: true, result: { response: JSON.stringify(good), usage: { prompt_tokens: 100, completion_tokens: 80, total_tokens: 180 } } }) };
  };
  await executeJob(job, ledger, persist, dispatch);
  assert.equal(ledger.attempts[0].state, 'completed');
  assert.deepEqual(ledger.attempts[0].mechanicalFailures, []);
  assert.equal(verifyLedger(ledger, 'test', jobs).size, 1);
  assert.equal(await executeJob(job, ledger, persist, dispatch), 'skipped');
  assert.equal(dispatches, 1);
  const reserved = { ...structuredClone(ledger), attempts: [{ ...ledger.attempts[0], state: 'reserved', accountedNeurons: job.reservedNeurons }] };
  assert.equal(await executeJob(job, reserved, persist, dispatch), 'skipped');
  assert.equal(dispatches, 1);
  await executeJob(jobs[1], ledger, persist, async () => { throw Object.assign(new Error(), { name: 'TimeoutError' }); });
  assert.equal(ledger.attempts[1].state, 'timeout');
  assert.equal(ledger.attempts[1].accountedNeurons, jobs[1].reservedNeurons);
  await executeJob(jobs[2], ledger, persist, async () => ({ status: 200, text: JSON.stringify({ success: true, result: { response: '{}' } }) }));
  assert.equal(ledger.attempts[2].accountedNeurons, jobs[2].reservedNeurons);
  const before = dispatches;
  await assert.rejects(executeJob(jobs[3], ledger, async () => { throw new Error('test_disk_failure'); }, dispatch));
  assert.equal(dispatches, before);
  assert.throws(() => verifyLedger({ ...ledger, attempts: [...ledger.attempts, ledger.attempts[0]] }, 'test', jobs));
  await assert.rejects(executeJob(jobs[0], { attempts: Array.from({ length: 12 }, (_, id) => ({ id: String(id), reservedNeurons: 1 })) }, persist, dispatch), /budget_exhausted/);
  await assert.rejects(executeJob(jobs[0], { attempts: [{ id: 'other', reservedNeurons: 1000 }] }, persist, dispatch), /budget_exhausted/);
  const largeFixture = structuredClone(fixture);
  largeFixture.scenarios[0].context.message = 'x'.repeat(6001);
  assert.throws(() => buildJobs(largeFixture), /prompt_byte_limit/);
  console.log('Offline self-test passed: constraints, bounds, reserve-before-I/O, complete/unknown usage, timeout, duplicate IDs and failed persistence. No inference or output files.');
}

async function main() {
  const args = process.argv.slice(2);
  let live = false; let test = false; let outputDir;
  for (let index = 0; index < args.length; index++) {
    if (args[index] === '--live' && !live) live = true;
    else if (args[index] === '--self-test' && !test) test = true;
    else if (args[index] === '--out' && !outputDir && args[index + 1] && !args[index + 1].startsWith('--')) outputDir = resolve(args[++index]);
    else fail('usage_expected_live_out_or_self_test');
  }
  if (live && test) fail('self_test_cannot_be_live');
  const fixtureText = await readFile(FIXTURE_PATH, 'utf8');
  const fixture = JSON.parse(fixtureText);
  const jobs = buildJobs(fixture);
  if (test) return selfTest(fixture, jobs);
  if (!live) {
    console.log(JSON.stringify({ mode: 'offline_no_inference_no_writes', policy: POLICY,
      totalReservedNeurons: jobs.reduce((sum, job) => sum + job.reservedNeurons, 0),
      jobs: jobs.map(({ id, model, promptBytes, reservedNeurons }) => ({ id, model: model.id, promptBytes, reservedNeurons })),
      liveCommand: 'CF_ACCOUNT_ID=<env> CF_API_TOKEN=<env> node scripts/benchmark-society-models.mjs --live --out /absolute/output/directory',
    }, null, 2));
    return;
  }
  if (!outputDir) fail('live_requires_explicit_output_directory');
  // Credentials are read ONLY after explicit --live; never searched or logged.
  const account = process.env.CF_ACCOUNT_ID;
  const token = process.env.CF_API_TOKEN;
  if (!account || !/^[a-f\d]{32}$/i.test(account) || !token || /\s/.test(token)) fail('missing_or_invalid_environment_credentials');
  const redact = (text) => text.replaceAll(token, '[REDACTED]').replaceAll(account, '[ACCOUNT]');
  const binding = hash(JSON.stringify({ fixtureText, policy: POLICY, models: MODELS, prompts: jobs.map((job) => job.payload), account: hash(account) }));
  await mkdir(outputDir, { recursive: true, mode: 0o700 });
  const lockPath = join(outputDir, '.lock');
  let lock;
  try { lock = await open(lockPath, 'wx', 0o600); } catch { fail('output_locked_check_recorded_process_before_resuming'); }
  try {
    await lock.writeFile(JSON.stringify({ pid: process.pid, startedAt: new Date().toISOString() }));
    await lock.sync();
    const ledgerPath = join(outputDir, 'ledger.json');
    let ledger;
    try { ledger = JSON.parse(await readFile(ledgerPath, 'utf8')); }
    catch (error) {
      if (error?.code !== 'ENOENT') fail('cannot_read_existing_ledger');
      try { await stat(`${ledgerPath}.tmp`); fail('incomplete_ledger_requires_manual_review'); }
      catch (pending) { if (pending?.code !== 'ENOENT') throw pending; }
      ledger = { version: 1, binding, createdAt: new Date().toISOString(), policy: POLICY, fixture, attempts: [] };
    }
    const seen = verifyLedger(ledger, binding, jobs);
    const persist = (value) => atomicJson(ledgerPath, value);
    let interrupted = false;
    let controller;
    const interrupt = () => { interrupted = true; controller?.abort(); };
    process.on('SIGINT', interrupt); process.on('SIGTERM', interrupt);
    try {
      for (const job of jobs) {
        if (interrupted) break;
        if (seen.has(job.id)) continue;
        const state = await executeJob(job, ledger, persist, async () => {
          if (interrupted) throw Object.assign(new Error(), { name: 'AbortError' });
          controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), POLICY.timeoutMs);
          try {
            const response = await fetch(`https://api.cloudflare.com/client/v4/accounts/${account}/ai/run/${job.model.id}`, {
              method: 'POST', redirect: 'error', signal: controller.signal,
              headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
              body: JSON.stringify(job.payload),
            });
            return { status: response.status, text: await responseText(response) };
          } finally { clearTimeout(timeout); controller = undefined; }
        }, redact);
        console.log(`${job.id}: ${state}; human review pending`);
        if (state !== 'completed' || ledger.attempts.at(-1).exceedsReservation) break;
      }
    } finally { process.off('SIGINT', interrupt); process.off('SIGTERM', interrupt); }
    const summary = report(ledger);
    await atomicJson(join(outputDir, 'report.json'), summary);
    console.log(JSON.stringify(summary, null, 2));
    if (summary.results.some((row) => row.state !== 'completed' || row.mechanicalFailures?.length)) process.exitCode = 2;
  } finally { await lock.close(); await unlink(lockPath); }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(`Benchmark stopped: ${error instanceof BenchError ? error.code : 'local_or_validation_failure'}. No automatic retry.`);
    process.exitCode = 1;
  });
}
